using System.Collections.Concurrent;
using System.Threading.Channels;
namespace MRS;
// Independent control/voice downconverters consume the shared I/Q capture. Capture never waits for decoding.
internal sealed record TrunkAudio(byte[] Pcm,long Hz,string Key,string Protocol,int? Radio=null,int? ColorCode=null);
internal sealed class TrunkRadio:IDisposable
{
    internal readonly object Sync=new();internal readonly TrunkFollower Model;
    private readonly Channel<(long Epoch,IqFrame Frame)> input=Channel.CreateBounded<(long,IqFrame)>(128);private readonly Task work;private long epoch,dropped,processed;private int inputFault;private volatile bool running,disposed;private readonly P25Pipeline controlP25=new();private DmrDecoder controlDmr=new();private CapStatusDecoder cap=new();private ReceiveDemodulator? controlDsp,voiceDsp;private P25VoiceDecoder? p25Voice;private readonly DigitalVoicePipeline dmrVoice=new();private DmrDecoder voiceIds=new();private readonly List<double> audioInput=[];
    private long controlCenter,controlFrequency,voiceCenter,voiceFrequency;private int controlRate,voiceRate;private string voiceKey="";private DmrFollowIdentity? dmrGate;private int voiceSlot=1;private long voiceSerial;private readonly ConcurrentQueue<(long Serial,byte[] Pcm)> audio=[];private readonly ConcurrentQueue<DmrReception> dmrObservations=[];private readonly ConcurrentQueue<PacketObservation> observations=[];private readonly ConcurrentQueue<TrunkEvent> discovered=[];
    internal long ProcessedBlocks=>Interlocked.Read(ref processed);internal long Dropped=>Interlocked.Read(ref dropped);internal string ReceiverStatus{get;private set;}="Stopped";internal string VoiceStatus{get;private set;}="No call";internal bool VoiceFits{get;private set;}internal bool ControlFits{get;private set;}internal long AudioFrames{get;private set;}
    internal TrunkRadio(string initialProtocol="P25"){Model=new(initialProtocol);dmrVoice.Audio+=pcm=>{if(audio.Count<32){var mono=new byte[pcm.Length];int slot=Volatile.Read(ref voiceSlot);for(int n=0;n+3<pcm.Length;n+=4){int p=n+(slot==2?2:0);mono[n]=mono[n+2]=pcm[p];mono[n+1]=mono[n+3]=pcm[p+1];}audio.Enqueue((Interlocked.Read(ref voiceSerial),mono));}};work=Task.Run(Work);}
    internal bool ExternalVoice{get;private set;}internal bool SuppressLocalVoice;
    internal bool Running=>running;
    internal void StartExternal(TrunkCall call,string source){Start(new(source,source,call.Protocol,call.Hz,[]));lock(Sync){ExternalVoice=true;Model.AssignExternal(call,source);}}
    internal void Start(TrunkProfile profile){lock(Sync){epoch++;ExternalVoice=false;ClearVoice();Model.Start(profile,DateTimeOffset.UtcNow);controlP25.Clear();controlP25.Enabled=profile.Protocol=="P25";controlDsp=null;controlDmr=new();cap=new();AttachDmr();Interlocked.Exchange(ref dropped,0);Interlocked.Exchange(ref processed,0);inputFault=0;running=true;AudioFrames=0;while(observations.TryDequeue(out _)){}while(dmrObservations.TryDequeue(out _)){}while(discovered.TryDequeue(out _)){}ReceiverStatus="Waiting for I/Q";}}
    private void AttachDmr(){controlDmr.Message+=o=>{var now=DateTimeOffset.UtcNow;long source=controlFrequency;if(dmrObservations.Count<256)dmrObservations.Enqueue(new(o,new($"trunk:{epoch}:{source}","Trunk "+Model.Profile.Name,false,source),now));if(discovered.Count<300)discovered.Enqueue(new(now,"Observed",$"CC {o.ColorCode}; {o.SystemType}; slot {o.Slot}; TG {o.Destination}; NET {o.Network}; SITE {o.Site}; rest LSN {o.RestChannel}. Frequency is observation source, not proof of advertised LSN.",source,o.Destination is uint tg?(int)tg:null));Model.ObserveDmr(o,source,now);if(cap.Feed(o,now) is {} status)Model.ObserveCap(status,source,now);};}
    internal void Stop(string reason="Stopped"){lock(Sync){running=false;epoch++;Model.Stop(DateTimeOffset.UtcNow,reason);ClearVoice();controlDsp=null;controlP25.Clear();ReceiverStatus=reason;}}
    private void ClearVoice(){voiceSerial++;voiceKey="";voiceFrequency=0;voiceDsp=null;p25Voice?.Dispose();p25Voice=null;dmrVoice.Configure(0,3,false);voiceIds=new();audioInput.Clear();dmrGate=null;VoiceStatus="No call";while(audio.TryDequeue(out _)){}}
    internal void Feed(IqFrame f){if(disposed||!running)return;int fault=f.Format is not(IqSampleFormat.Unsigned8 or IqSampleFormat.Signed8)?2:0;if(fault==0&&(f.Data.Length>65536||!input.Writer.TryWrite((Interlocked.Read(ref epoch),f with{Data=(byte[])f.Data.Clone()}))))fault=1;if(fault!=0){Interlocked.Increment(ref dropped);Interlocked.Exchange(ref inputFault,fault);}}
    internal void Tick(){lock(Sync){Model.Tick(DateTimeOffset.UtcNow);if(Model.Active==null&&voiceKey.Length>0)ClearVoice();}}
    internal TrunkAudio[] DrainAudio(){var result=new List<TrunkAudio>();lock(Sync){while(audio.TryDequeue(out var a)){if(!Model.Running||Model.Active==null||a.Serial!=voiceSerial)continue;if(Model.Active.Protocol!="P25"&&dmrGate?.Confirmed!=true)continue;Model.Voice(DateTimeOffset.UtcNow);var c=Model.Active;result.Add(new(a.Pcm,c.Hz,$"{c.Protocol}:{c.Hz}:{c.Slot}:{c.Talkgroup}:{c.First.UtcTicks}",c.Protocol,c.Radio,c.ColorCode));AudioFrames+=a.Pcm.Length/4;}}return result.ToArray();}
    internal DmrReception[] DrainDmr(){var rows=new List<DmrReception>();while(dmrObservations.TryDequeue(out var row))rows.Add(row);return rows.ToArray();}
    internal PacketObservation[] DrainObservations(){var rows=new List<PacketObservation>();while(observations.TryDequeue(out var r))rows.Add(r);return rows.ToArray();}
    internal TrunkEvent[] DrainDiscovery(){var rows=new List<TrunkEvent>();while(discovered.TryDequeue(out var r))rows.Add(r);return rows.ToArray();}
    private static bool Fits(IqFrame f,long hz,double width)=>hz-width/2>=f.Frequency-f.Capture.UsableBandwidthHz/2&&hz+width/2<=f.Frequency+f.Capture.UsableBandwidthHz/2;
    private async Task Work(){await foreach(var block in input.Reader.ReadAllAsync()){lock(Sync){if(disposed||block.Epoch!=epoch||!Model.Running)continue;try{int fault=Interlocked.Exchange(ref inputFault,0);if(fault!=0){Stop(fault==2?"Unsupported I/Q format":"Trunk I/Q overrun; stopped. Reduce sample rate, then restart following.");continue;}Process(block.Frame);Interlocked.Increment(ref processed);if(!Model.Running)running=false;}catch(Exception ex){Stop("Trunk decoder stopped: "+ex.Message);}}}}
    private void Process(IqFrame f)
    {
        var now=DateTimeOffset.UtcNow;Model.Tick(now);byte[] bytes=f.Data;if(f.Format==IqSampleFormat.Signed8){bytes=(byte[])bytes.Clone();for(int n=0;n<bytes.Length;n++)bytes[n]^=128;}
        bool p25=Model.Profile.Protocol=="P25";ControlFits=Fits(f,Model.ControlHz,p25?16000:12500);
        if(ControlFits&&!ExternalVoice){if(controlDsp==null||controlCenter!=f.Frequency||controlRate!=f.Rate||controlFrequency!=Model.ControlHz){controlDsp=new("NFM",f.Rate,Model.ControlHz-f.Frequency,p25?16000:12500){CaptureData=true};controlCenter=f.Frequency;controlRate=f.Rate;controlFrequency=Model.ControlHz;controlP25.Reacquire();controlDmr=new();cap=new();AttachDmr();}
            controlDsp.Process(bytes);if(p25){controlP25.Feed(controlDsp.DataSamples,new($"trunk:{epoch}:control",$"Trunk {Model.Profile.Name}",false,controlFrequency));foreach(var row in controlP25.Drain()){Model.ObserveP25(row,now);if(observations.Count<256)observations.Enqueue(row);}}
            else controlDmr.Process(controlDsp.DataSamples);ReceiverStatus="Control/rest monitored inside capture";}
        else ReceiverStatus=ExternalVoice?"Dedicated voice receiver - control is on another receiver":"Control outside capture - suspended during hardware retune";
        if(SuppressLocalVoice&&!ExternalVoice){if(voiceKey.Length>0)ClearVoice();return;}if(Model.Active is not {} call){if(voiceKey.Length>0)ClearVoice();VoiceFits=false;return;}
        VoiceFits=Fits(f,call.Hz,call.Protocol=="P25"?16000:12500);if(!VoiceFits){VoiceStatus="Voice outside capture; retune required";return;}
        string key=$"{call.Protocol}:{call.Hz}:{call.Slot}:{call.Talkgroup}:{call.Nac}:{call.First.UtcTicks}";
        if(key!=voiceKey){ClearVoice();voiceKey=key;long serial=voiceSerial;if(call.Protocol=="P25"){p25Voice=new(){ExpectedNac=call.Nac,ExpectedGroup=call.Talkgroup};p25Voice.Audio+=pcm=>{if(audio.Count<32)audio.Enqueue((serial,pcm));};}else{Volatile.Write(ref voiceSlot,call.Slot);dmrVoice.Configure(1,call.Slot,false);voiceIds=new();var gate=dmrGate=new DmrFollowIdentity(call);voiceIds.Message+=o=>{var action=gate.Observe(o);if(action==DmrFollowAction.Terminator)Model.End(DateTimeOffset.UtcNow,"DMR terminator for selected TG/slot/color code");else if(action==DmrFollowAction.HeaderAccepted)Model.ConfirmDmrVoice(gate.ColorCode!.Value,o.Source);};}}
        if(voiceDsp==null||voiceCenter!=f.Frequency||voiceRate!=f.Rate||voiceFrequency!=call.Hz){voiceDsp=new("NFM",f.Rate,call.Hz-f.Frequency,call.Protocol=="P25"?16000:12500){CaptureData=true};voiceCenter=f.Frequency;voiceRate=f.Rate;voiceFrequency=call.Hz;}
        voiceDsp.Process(bytes);var samples=voiceDsp.DataSamples;
        if(p25Voice!=null){p25Voice.Feed(samples);VoiceStatus=p25Voice.Status;if(VoiceStatus=="Call ended")Model.End(now,"P25 terminator");}else{voiceIds.Process(samples);audioInput.AddRange(samples);while(audioInput.Count>=960){var chunk=audioInput.Take(960).ToArray();audioInput.RemoveRange(0,960);dmrVoice.Feed(chunk,new(key,"Trunk voice",false,call.Hz));}VoiceStatus=dmrGate?.Confirmed==true?dmrVoice.Status:"Awaiting validated TG/slot voice identity; audio muted";}
    }
    public void Dispose(){Stop();lock(Sync){disposed=true;input.Writer.TryComplete();}work.GetAwaiter().GetResult();dmrVoice.Dispose();}
}
